<style>
/* Layout only. Colors, typography and controls come from the active Panel theme. */
.imm-progress{appearance:none;border:0;border-radius:.5rem;overflow:hidden;background:var(--gray-200)}.imm-progress::-webkit-progress-bar{background:var(--gray-200);border-radius:.5rem}.imm-progress::-webkit-progress-value{background:var(--primary-500);border-radius:.5rem}.imm-progress::-moz-progress-bar{background:var(--primary-500);border-radius:.5rem}.dark .imm-progress,.dark .imm-progress::-webkit-progress-bar{background:var(--gray-700)}
.imm-install-status:not(:has(section)){display:none}.imm-install-status{position:sticky;top:.75rem;z-index:10}.imm-progress{display:block;width:100%;height:.65rem;accent-color:var(--primary-500,#3b82f6)}.imm-progress-file{white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.imm-install-history{margin-top:1rem}.imm-install-history summary{cursor:pointer}.imm-install-history>div{margin-top:1rem;max-height:16rem;overflow:auto}
.imm-loading{position:fixed;right:1.5rem;bottom:1.5rem;z-index:30;pointer-events:none}.imm-loading svg{width:1.25rem;height:1.25rem;display:inline-block}.imm,.imm-form,.imm-selection{display:grid;gap:1.5rem;min-width:0}.imm-row{display:flex;align-items:center;gap:.75rem;flex-wrap:wrap}.imm-between{justify-content:space-between}.imm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,280px),1fr));gap:1.5rem}.imm-grid>article,.imm-project{height:100%;min-width:0}.imm-project>.fi-section-content-ctn>.fi-section-content{display:flex;flex-direction:column;gap:1rem;height:100%}.imm-project-heading{display:flex;gap:1rem;align-items:center}.imm-project-heading>div{min-width:0}.imm-thumbnail{width:3rem;height:3rem;object-fit:cover;flex-shrink:0;border-radius:.5rem}.imm-description{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}.imm-project .fi-btn{margin-top:auto;align-self:flex-start}.imm-summary,.imm-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.5rem}.imm-summary{margin-bottom:1.5rem}.imm-summary dd{margin-top:.5rem;font-weight:600}.imm-fields{grid-template-columns:repeat(2,minmax(0,1fr))}.imm p,.imm li,.imm dd{overflow-wrap:anywhere}.imm-form label{display:grid;gap:.5rem}.imm-form ul{display:grid;gap:.75rem}
@media(max-width:640px){.imm-summary,.imm-fields{grid-template-columns:1fr}.imm{gap:1rem}}
.imm-queue-items{max-height:16rem;overflow-y:auto;overflow-x:hidden;padding:.75rem}.imm-queue-items .imm-row>div{min-width:0;flex:1}.imm-queue-items strong{overflow-wrap:anywhere}
.imm-catalog-list{display:grid;gap:1rem}.imm-catalog-list .imm-project>.fi-section-content-ctn>.fi-section-content{display:flex;flex-direction:row;align-items:center;gap:1.5rem}.imm-catalog-copy{display:grid;gap:.75rem;min-width:0;flex:1}.imm-quick-install{display:grid;gap:.75rem;flex:0 0 15rem;min-width:0}.imm-quick-install .fi-btn{margin:0}.imm-quick-install p{overflow-wrap:anywhere}.imm-project-heading button{text-align:start;cursor:pointer}.imm-project-heading button:hover{text-decoration:underline}@media(max-width:768px){.imm-catalog-list .imm-project>.fi-section-content-ctn>.fi-section-content{flex-direction:column;align-items:stretch}.imm-quick-install{flex:initial}}
.imm-pagination{justify-content:center}
.imm-release-field,.imm-release-field .fi-input-wrp,.imm-release-field select{min-width:0;max-width:100%}.imm-release-field select{width:100%;text-overflow:ellipsis}.imm-release-support{min-width:0;max-width:100%;white-space:normal;overflow-wrap:anywhere}
</style>
